<body>
<div id="wrap">
  <canvas id="game" width="800" height="600"></canvas>
  <div id="hud">score: <b id="score">0</b> &nbsp;|&nbsp; wave: <b id="wave">1</b> &nbsp;|&nbsp; lives: <b id="lives">3</b></div>
</div>

<script>
(function () {
  'use strict';

  var canvas = document.getElementById('game');
  var ctx = canvas.getContext('2d');
  var W = canvas.width;
  var H = canvas.height;

  var scoreEl = document.getElementById('score');
  var waveEl = document.getElementById('wave');
  var livesEl = document.getElementById('lives');

  // ---------- Input ----------
  var keys = {};
  var spacePressed = false;
  var prevSpace = false;

  window.addEventListener('keydown', function (e) {
    if (e.code === 'Space') {
      e.preventDefault();
      keys['Space'] = true;
    }
    keys[e.code] = true;
  });

  window.addEventListener('keyup', function (e) {
    if (e.code === 'Space') keys['Space'] = false;
    keys[e.code] = false;
  });

  window.addEventListener('blur', function () {
    keys = {};
  });

  // ---------- Mouse buttons on start/gameover screens ----------
  canvas.addEventListener('click', function () {
    if (state === 'start' || state === 'gameover') {
      startGame();
    }
  });

  // ---------- Game state ----------
  var state = 'start';

  var player = null;
  var enemies = [];
  var bullets = [];
  var ebullets = [];
  var particles = [];
  var stars = [];

  var score = 0;
  var wave = 1;
  var lives = 3;
  var spawnTimer = 0;
  var spawnRate = 1.2;
  var invulnTimer = 0;
  var shake = 0;

  function makeStars(n) {
    stars = [];
    for (var i = 0; i < n; i++) {
      stars.push({
        x: Math.random() * W,
        y: Math.random() * H,
        s: 0.5 + Math.random() * 1.5,
        v: 30 + Math.random() * 90
      });
    }
  }

  function resetGame() {
    player = { x: W / 2, y: H - 60, w: 34, h: 34, speed: 280 };
    enemies = [];
    bullets = [];
    ebullets = [];
    particles = [];
    score = 0;
    wave = 1;
    lives = 3;
    spawnTimer = 0;
    spawnRate = 1.2;
    invulnTimer = 1.5;
    shake = 0;
    updateHud();
  }

  function startGame() {
    resetGame();
    state = 'playing';
  }

  function updateHud() {
    scoreEl.textContent = score;
    waveEl.textContent = wave;
    livesEl.textContent = lives;
  }

  // ---------- Entity helpers ----------
  function spawnEnemy() {
    var type = Math.random();
    var e;
    if (wave >= 3 && type < 0.18 && enemies.length < 8) {
      // Big tough ship
      e = {
        x: Math.random() * (W - 70) + 35,
        y: -60,
        w: 56, h: 46,
        hp: 3, maxHp: 3,
        vx: (Math.random() - 0.5) * 60,
        vy: 35 + 10 * Math.random() + wave * 4,
        score: 50,
        kind: 'big'
      };
    } else {
      e = {
        x: Math.random() * (W - 44) + 22,
        y: -50,
        w: 36, h: 30,
        hp: 1, maxHp: 1,
        vx: (Math.random() - 0.5) * 80,
        vy: 50 + 20 * Math.random() + wave * 6,
        score: 10,
        kind: 'small'
      };
    }
    enemies.push(e);
  }

  function fireBullet() {
    bullets.push({
      x: player.x,
      y: player.y - 20,
      w: 4, h: 14,
      vy: -520,
      vx: 0
    });
    // small muzzle particles
    for (var i = 0; i < 3; i++) {
      particles.push({
        x: player.x + (Math.random() - 0.5) * 8,
        y: player.y - 20,
        vx: (Math.random() - 0.5) * 60,
        vy: -60 - Math.random() * 40,
        life: 0.2 + Math.random() * 0.2,
        maxLife: 0.4,
        size: 2,
        color: '#7ef0ff'
      });
    }
  }

  function explode(x, y, color, count) {
    var n = count || 18;
    for (var i = 0; i < n; i++) {
      var a = Math.random() * Math.PI * 2;
      var sp = 60 + Math.random() * 220;
      particles.push({
        x: x,
        y: y,
        vx: Math.cos(a) * sp,
        vy: Math.sin(a) * sp,
        life: 0.4 + Math.random() * 0.7,
        maxLife: 1.1,
        size: 1.5 + Math.random() * 2.5,
        color: color
      });
    }
  }

  // ---------- Update ----------
  function update(dt) {
    // stars drift always
    for (var i = 0; i < stars.length; i++) {
      var st = stars[i];
      st.y += st.v * dt;
      if (st.y > H) { st.y = -2; st.x = Math.random() * W; }
    }

    if (state === 'start') return;
    if (state === 'gameover') {
      updateParticles(dt);
      return;
    }

    // shake decay
    if (shake > 0) shake = Math.max(0, shake - dt * 30);
    if (invulnTimer > 0) invulnTimer -= dt;

    // Player movement
    var dx = 0, dy = 0;
    if (keys['ArrowLeft'] || keys['KeyA']) dx -= 1;
    if (keys['ArrowRight'] || keys['KeyD']) dx += 1;
    if (keys['ArrowUp'] || keys['KeyW']) dy -= 1;
    if (keys['ArrowDown'] || keys['KeyS']) dy += 1;

    if (dx !== 0 && dy !== 0) {
      dx *= 0.7071;
      dy *= 0.7071;
    }
    player.x += dx * player.speed * dt;
    player.y += dy * player.speed * dt;
    player.x = Math.max(18, Math.min(W - 18, player.x));
    player.y = Math.max(18, Math.min(H - 18, player.y));

    // Shooting (edge-triggered on space)
    var space = !!keys['Space'];
    if (space && !prevSpace) {
      fireBullet();
    }
    prevSpace = space;

    // Spawn enemies
    spawnTimer -= dt;
    if (spawnTimer <= 0) {
      spawnEnemy();
      spawnTimer = Math.max(0.35, spawnRate - (wave - 1) * 0.08) * (0.7 + Math.random() * 0.6);
      // enemy fire chance rises with wave
      if (wave >= 2) {
        var shooters = enemies.filter(function (e) { return e.kind === 'small'; });
        var r = Math.random();
        if (shooters.length > 0 && r < 0.02 + wave * 0.01) {
          var shooter = shooters[Math.floor(Math.random() * shooters.length)];
          ebullets.push({
            x: shooter.x, y: shooter.y + 15,
            w: 5, h: 5, vy: 240 + wave * 12, vx: (Math.random() - 0.5) * 40
          });
        }
      }
    }

    // Wave progression
    var waveTarget = 4 + wave * 2;
    if (score >= scoreForWave(wave) && enemies.length === 0) {
      wave++;
      spawnRate = Math.max(0.4, spawnRate - 0.12);
      waveEl.textContent = wave;
    }

    // Move bullets
    for (i = bullets.length - 1; i >= 0; i--) {
      var b = bullets[i];
      b.y += b.vy * dt;
      if (b.y < -20) bullets.splice(i, 1);
    }

    // Move enemy bullets
    for (i = ebullets.length - 1; i >= 0; i--) {
      var eb = ebullets[i];
      eb.x += eb.vx * dt;
      eb.y += eb.vy * dt;
      if (eb.y > H + 20 || eb.x < -20 || eb.x > W + 20) ebullets.splice(i, 1);
    }

    // Move enemies
    for (i = enemies.length - 1; i >= 0; i--) {
      var e = enemies[i];
      e.x += e.vx * dt;
      e.y += e.vy * dt;
      if (e.x < 20 || e.x > W - 20) {
        e.vx *= -1;
        e.x = Math.max(20, Math.min(W - 20, e.x));
      }
      if (e.y - e.h > H) {
        enemies.splice(i, 1);
      }
    }

    // Bullets vs enemies
    for (i = bullets.length - 1; i >= 0; i--) {
      var bl = bullets[i];
      var hit = false;
      for (var j = enemies.length - 1; j >= 0; j--) {
        var en = enemies[j];
        if (rectOverlap(bl, en)) {
          en.hp--;
          hit = true;
          explode(bl.x, en.y, '#ffd166', 6);
          if (en.hp <= 0) {
            score += en.score;
            explode(en.x, en.y, en.kind === 'big' ? '#ff6b6b' : '#7ef0ff', en.kind === 'big' ? 30 : 16);
            enemies.splice(j, 1);
            shake = Math.min(12, shake + 3);
          }
          break;
        }
      }
      if (hit) {
        bullets.splice(i, 1);
      }
    }

    // Enemies vs player (collision)
    if (invulnTimer <= 0) {
      for (i = enemies.length - 1; i >= 0; i--) {
        var en2 = enemies[i];
        if (rectOverlap(en2, shrink(player, 6))) {
          lives--;
          invulnTimer = 1.8;
          explode(en2.x, en2.y, '#ff6b6b', 24);
          enemies.splice(i, 1);
          shake = 14;
          hitPlayer(en2.x, en2.y);
          renderFlash = 0.25;
          if (lives <= 0) {
            state = 'gameover';
            explode(player.x, player.y, '#ff6b6b', 40);
            shake = 18;
          }
          break;
        }
      }
    }

    // Enemy bullets vs player
    if (invulnTimer <= 0) {
      for (i = ebullets.length - 1; i >= 0; i--) {
        var eb2 = ebullets[i];
        if (rectOverlap(eb2, shrink(player, 6))) {
          ebullets.splice(i, 1);
          lives--;
          invulnTimer = 1.8;
          explode(eb2.x, eb2.y, '#ff6b6b', 12);
          shake = 10;
          renderFlash = 0.25;
          if (lives <= 0) {
            state = 'gameover';
            explode(player.x, player.y, '#ff6b6b', 40);
            shake = 18;
          }
          break;
        }
      }
    }

    updateHud();
    updateParticles(dt);
  }

  var renderFlash = 0;

  function scoreForWave(w) {
    var t = 0;
    for (var i = 1; i < w; i++) t += 4 + i * 2;
    return t;
  }

  function shrink(r, n) {
    return { x: r.x, y: r.y, w: Math.max(4, r.w - n), h: Math.max(4, r.h - n) };
  }

  function rectOverlap(a, b) {
    return a.x - a.w / 2 < b.x + b.w / 2 &&
           a.x + a.w / 2 > b.x - b.w / 2 &&
           a.y - a.h / 2 < b.y + b.h / 2 &&
           a.y + a.h / 2 > b.y - b.w / 2;
  }

  function hitPlayer(x, y) {
    // placeholder: no-op, particles handled in explode callers
    void x; void y;
  }

  function updateParticles(dt) {
    for (var i = particles.length - 1; i >= 0; i--) {
      var p = particles[i];
      p.life -= dt;
      if (p.life <= 0) { particles.splice(i, 1); continue; }
      p.x += p.vx * dt;
      p.y += p.vy * dt;
      p.vx *= 0.98;
      p.vy *= 0.98;
    }
  }

  // ---------- Render ----------
  function drawShip(g, color) {
    g.fillStyle = color;
    g.beginPath();
    g.moveTo(9, -13);
    g.lineTo(-9, -13);
    g.lineTo(-6, -4);
    g.lineTo(-16, 2);
    g.lineTo(-16, 10);
    g.lineTo(16, 10);
    g.lineTo(16, 2);
    g.lineTo(6, -4);
    g.closePath();
    g.fill();
  }

  function render() {
    ctx.save();
    ctx.clearRect(0, 0, W, H);

    if (shake > 0) {
      ctx.translate((Math.random() - 0.5) * shake, (Math.random() - 0.5) * shake);
    }

    // stars
    ctx.fillStyle = '#ffffff';
    for (var i = 0; i < stars.length; i++) {
      var st = stars[i];
      ctx.globalAlpha = 0.4 + 0.6 * (st.s / 2);
      ctx.fillRect(st.x, st.y, st.s, st.s);
    }
    ctx.globalAlpha = 1;

    // particles
    for (i = 0; i < particles.length; i++) {
      var p = particles[i];
      ctx.globalAlpha = Math.max(0, p.life / p.maxLife);
      ctx.fillStyle = p.color;
      ctx.fillRect(p.x - p.size / 2, p.y - p.size / 2, p.size, p.size);
    }
    ctx.globalAlpha = 1;

    if (state === 'start') {
      renderStart();
      ctx.restore();
      return;
    }

    if (state !== 'gameover' && player) {
      // player (blink when invulnerable)
      var blink = invulnTimer > 0 && Math.floor(invulnTimer * 10) % 2 === 0;
      ctx.save();
      ctx.translate(player.x, player.y);
      if (blink) ctx.globalAlpha = 0.4;
      ctx.shadowColor = '#7ef0ff';
      ctx.shadowBlur = 14;
      drawShip(ctx, '#9ae6ff');
      ctx.shadowBlur = 0;
      // cockpit
      ctx.fillStyle = '#ffffff';
      ctx.beginPath();
      ctx.arc(0, 0, 3, 0, Math.PI * 2);
      ctx.fill();
      // engine flame
      ctx.fillStyle = '#ff9f43';
      var fl = 6 + Math.random() * 6;
      ctx.beginPath();
      ctx.moveTo(-4, 10);
      ctx.lineTo(0, 10 + fl);
      ctx.lineTo(4, 10);
      ctx.closePath();
      ctx.fill();
      ctx.restore();
      ctx.globalAlpha = 1;
    }

    // enemies
    for (i = 0; i < enemies.length; i++) {
      var e = enemies[i];
      ctx.save();
      ctx.translate(e.x, e.y);
      if (e.kind === 'big') {
        ctx.shadowColor = '#ff6b6b';
        ctx.shadowBlur = 12;
        ctx.fillStyle = '#b23a48';
        drawShip(ctx, '#b23a48');
        ctx.fillStyle = '#ffd166';
        ctx.fillRect(-10, 2, 20, 3);
      } else {
        ctx.shadowColor = '#c084fc';
        ctx.shadowBlur = 8;
        ctx.fillStyle = '#7c3aed';
        drawShip(ctx, '#7c3aed');
        ctx.fillStyle = '#c084fc';
        ctx.fillRect(-4, -6, 8, 3);
      }
      ctx.restore();
      // hp bar for big
      if (e.kind === 'big' && e.hp < e.maxHp) {
        ctx.fillStyle = 'rgba(255,255,255,0.25)';
        ctx.fillRect(e.x - 16, e.y - 24, 32, 4);
        ctx.fillStyle = '#ff6b6b';
        ctx.fillRect(e.x - 16, e.y - 24, 32 * (e.hp / e.maxHp), 4);
      }
    }

    // bullets
    ctx.save();
    ctx.shadowColor = '#7ef0ff';
    ctx.shadowBlur = 8;
    ctx.fillStyle = '#7ef0ff';
    for (i = 0; i < bullets.length; i++) {
      ctx.fillRect(bullets[i].x - 2, bullets[i].y - 7, 4, 14);
    }
    ctx.restore();

    // enemy bullets
    ctx.save();
    ctx.shadowColor = '#ff6b6b';
    ctx.shadowBlur = 8;
    ctx.fillStyle = '#ff6b6b';
    for (i = 0; i < ebullets.length; i++) {
      ctx.beginPath();
      ctx.arc(ebullets[i].x, ebullets[i].y, 3, 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.restore();

    if (state === 'gameover') {
      renderGameOver();
    }

    ctx.restore();

    // red vignette flash on hit
    if (renderFlash > 0) {
      renderFlash -= 1 / 60;
      ctx.fillStyle = 'rgba(255, 60, 60, ' + Math.max(0, renderFlash) * 0.4 + ')';
      ctx.fillRect(0, 0, W, H);
    }
  }

  function renderStart() {
    ctx.fillStyle = 'rgba(5, 6, 15, 0.55)';
    ctx.fillRect(0, 0, W, H);

    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';

    ctx.fillStyle = '#7ef0ff';
    ctx.font = 'bold 46px "Courier New", monospace';
    ctx.shadowColor = '#7ef0ff';
    ctx.shadowBlur = 20;
    ctx.fillText('SPACE SHOOTER', W / 2, H / 2 - 120);
    ctx.shadowBlur = 0;

    ctx.fillStyle = '#cfe8ff';
    ctx.font = '16px "Courier New", monospace';
    ctx.fillText('Arrow keys / WASD to move', W / 2, H / 2 - 60);
    ctx.fillText('SPACE to shoot', W / 2, H / 2 - 30);
    ctx.fillText('Destroy the invaders, survive the waves', W / 2, H / 2);

    ctx.fillStyle = '#7ef0ff';
    ctx.font = 'bold 20px "Courier New", monospace';
    var pulse = 0.6 + 0.4 * Math.sin(Date.now() / 300);
    ctx.globalAlpha = pulse;
    ctx.fillText('PRESS CLICK OR ENTER TO START', W / 2, H / 2 + 70);
    ctx.globalAlpha = 1;

    ctx.fillStyle = '#5f7aa8';
    ctx.font = '13px "Courier New", monospace';
    ctx.fillText('defend the galaxy', W / 2, H / 2 + 130);
  }

  function renderGameOver() {
    ctx.fillStyle = 'rgba(5, 6, 15, 0.7)';
    ctx.fillRect(0, 0, W, H);

    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillStyle = '#ff6b6b';
    ctx.font = 'bold 42px "Courier New", monospace';
    ctx.shadowColor = '#ff6b6b';
    ctx.shadowBlur = 18;
    ctx.fillText('GAME OVER', W / 2, H / 2 - 50);
    ctx.shadowBlur = 0;

    ctx.fillStyle = '#cfe8ff';
    ctx.font = '18px "Courier New", monospace';
    ctx.fillText('Score: ' + score + '   |   Wave ' + wave, W / 2, H / 2 + 5);

    ctx.fillStyle = '#7ef0ff';
    ctx.font = 'bold 18px "Courier New", monospace';
    ctx.globalAlpha = 0.6 + 0.4 * Math.sin(Date.now() / 300);
    ctx.fillText('CLICK TO PLAY AGAIN', W / 2, H / 2 + 60);
    ctx.globalAlpha = 1;
  }

  // ---------- Main loop ----------
  var last = performance.now();

  function loop(now) {
    var dt = Math.min(0.05, (now - last) / 1000);
    last = now;
    update(dt);
    render();
    requestAnimationFrame(loop);
  }

  // Enter to start
  window.addEventListener('keydown', function (e) {
    if (e.code === 'Enter' && (state === 'start' || state === 'gameover')) {
      startGame();
    }
  });

  makeStars(140);
  resetGame();
  requestAnimationFrame(loop);
})();
